class Solution:
    def minimumPartition(self, s: str, k: int) -> int:
        INF = float('inf')
        n = len(s)
        max_len = len(str(k))
        dp = [INF] * (n + 1)
        dp[0] = 0
        for i in range(1, n + 1):
            val = 0
            pw = 1
            for ln in range(1, min(i, max_len) + 1):
                d = int(s[i - ln])
                val += d * pw
                pw *= 10
                if d > k:
                    break
                if val <= k and dp[i - ln] + 1 < dp[i]:
                    dp[i] = dp[i - ln] + 1
        return dp[n] if dp[n] < INF else -1

