class Solution {
    public int minimumPartition(String s, int k) {
        int n = s.length();
        int maxLen = Integer.toString(k).length();
        long[] dp = new long[n + 1];
        Arrays.fill(dp, Long.MAX_VALUE / 2);
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            long val = 0, pw = 1;
            for (int ln = 1; ln <= Math.min(i, maxLen); ln++) {
                int d = s.charAt(i - ln) - '0';
                val += d * pw; pw *= 10;
                if (d > k) break;
                if (val <= k && dp[i - ln] + 1 < dp[i]) dp[i] = dp[i - ln] + 1;
            }
        }
        return dp[n] >= Long.MAX_VALUE / 2 ? -1 : (int) dp[n];
    }
}

